function parseWeek(text){
  const lines=westDigits(text).split("\n").filter(l=>l.split("|").length>=5),start=new Date(),out=[];
  const dayIdx=s=>{s=s.replace("الاثنين","الإثنين").replace("الاربعاء","الأربعاء").trim();for(let i=0;i<7;i++){if(s.includes(WD[i].replace("ال","")))return i;}return -1;};
  const dmap=s=>/أشغال|اشغال/.test(s)?"works":/شرط/.test(s)?"police":/صح|مفرزة/.test(s)?"health":/نشاط/.test(s)?"act":/بيان/.test(s)?"official":/أخبار|اخبار/.test(s)?"news":"general";
  const tmap=s=>/ستوري/.test(s)?"story":/كاروسيل|شرائح/.test(s)?"carousel":/فلوغ/.test(s)?"vlog":/لايف|مباشر/.test(s)?"live":/ريل|فيديو/.test(s)?"reel":"post";
  lines.forEach((l,n)=>{const c=l.split("|").map(x=>x.replace(/[*#]/g,"").trim());if(/^اليوم$/.test(c[0]))return;
    let di=dayIdx(c[0]);let d;if(di<0)d=addDays(start,Math.min(n,6));else{d=new Date(start);while(d.getDay()!==di)d=addDays(d,1);}
    let tm=(c[1].match(/(\d{1,2})(?::(\d{2}))?/)||[]);let h=+tm[1]||19,mi=+tm[2]||0;if(/مساء|مسا|ليل|pm/i.test(c[1])&&h<12)h+=12;
    out.push({id:uid(),date:iso(d),time:`${p2(h)}:${p2(mi)}`,title:c[4]||"منشور",dept:dmap(c[2]),type:tmap(c[3]),plat:["fb","ig"],status:"idea",caption:"",notes:c[5]?"الهوك: "+c[5]:""});});
  return out;}

/* ٨ أفكار اليوم */
let DV={date:null,open:-1};
function dailyBlock(){
  if(!DV.date)DV.date=TODAY();
  const ds=DV.date,ideas=dailyIdeas(ds,(S.daily.rolls||{})[ds]),d=pIso(ds),rel=ds===TODAY()?"اليوم":ds===iso(addDays(new Date(),1))?"بكرا":ds===iso(addDays(new Date(),-1))?"مبارح":"";
  return `<h2 class="s" id="daily">٨ أفكار فيديو ${rel?"— "+rel:""}</h2>
  <div class="card gold">
    <div class="row" style="justify-content:space-between;margin-bottom:10px"><button class="btn l sm" data-act="dvDay" data-d="-1">‹ قبل</button><b>${arDate(d)}</b><button class="btn l sm" data-act="dvDay" data-d="1">بعد ›</button></div>
    <p class="hint" style="margin:0 0 10px">كل يوم ٨ أفكار جديدة، ولكل وحدة التصوير خطوة خطوة (وين تحط التلفون) والمونتاج على كاب كات. إذا ما عجبتك فكرة، اكبس «بدّلها».</p>
    <div class="list">${ideas.map((x,i)=>{const done=!!S.daily.done[ds+"|"+i];return `<details class="dv" ${DV.open===i?"open":""} data-i="${i}">
      <summary><span class="n" style="background:${deptDot(x.dept)}">${done?"✓":i+1}</span><span><b>${esc(x.title)}</b><span class="meta"><span class="chip">${(DEPTS[x.dept]||DEPTS.general).n}</span><span class="chip">${x.fn}</span><span class="chip">${x.dur} ث</span></span></span></summary>
      <div class="dvb">
        <div class="hk">🎯 الهوك: ${esc(x.hook)}</div>
        <div class="lbl">🎥 التصوير</div>
        <ol class="shots">${x.shots.map(s=>`<li><b>${esc(s[0])}</b><span>📱 ${esc(s[1])} · ${s[2]} ث</span></li>`).join("")}</ol>
        <div class="lbl">✂️ المونتاج على كاب كات</div>
        <ul class="do">${x.edit.map(e=>`<li>${esc(e)}</li>`).join("")}</ul>
        <div class="lbl">✍️ الكابشن <small style="color:var(--ink3)">· النشر ${POST_TIME[x.f]||"19:00"}</small></div>
        <div class="out" style="max-height:none;padding:10px 12px;font-size:13.5px">${esc(x.cap)}</div>
        <div class="row" style="margin-top:10px"><button class="btn g sm" data-act="dvCal" data-i="${i}">${ic("calendar",16)} حطّها بالتقويم</button><button class="btn l sm" data-act="dvCap" data-i="${i}">نسخ الكابشن</button><button class="btn l sm" data-act="dvDone" data-i="${i}">${done?"↺ ما صوّرتها":"✓ صوّرتها"}</button><button class="btn o sm" data-act="dvRoll" data-i="${i}">🎲 بدّلها</button><button class="btn o sm" data-act="dvScript" data-i="${i}">✦ سكربت أعمق</button></div>
      </div></details>`;}).join("")}</div>
    <div class="row" style="margin-top:12px"><button class="btn l sm" data-act="dvCopyAll">نسخ الـ٨ كلّهن</button><button class="btn l sm" data-act="dvWa">واتساب</button><button class="btn o sm" data-act="dvAI">✦ ٨ أفكار جديدة كلياً بالـAI</button></div>
  </div>`;}
